from collections import deque

WINDOW = 600
MAX_REQUESTS = 3
HALF_OPEN_WINDOW = 300

def solve(timestamps, services, results):

    breakers = {
        'B': {
            'state': 'closed',
            'failures': deque(),
            'open_time': None,
        },
        'C': {
            'state': 'closed',
            'failures':  deque(),
            'open_time': None
        }
    }

    answers = []

    for i, timestamp in enumerate(timestamps):
        timestamp = int(timestamp)
        service = services[i]
        result  = result[i]

        breaker = breakers[service]

        if breaker['state'] == "open" and timestamp - breaker['open_time'] >= HALF_OPEN_WINDOW:
            breaker['state'] = "half_open"

        if breaker['state'] == "open":
            answers.append("BLOCKED")
            continue

        if breaker['state'] == "half_open":
            if result == "OK":
                breaker["state"] = "closed"
                breaker["failures"].clear()
                answers.append("OK")
            else:
                breaker['state'] = "open"
                breaker['open_time'] = timestamp
                answers.append("FAIL")
            continue

        if result == "OK":
            answers.append("OK")
        else:
            failures = breaker['failures']

            while failures and failures[0] < timestamp - WINDOW:
                failures.popleft()

            failures.append(timestamp)

            if len(failures) >= 3:
                breaker["state"] = "open"
                breaker["open_time"] = timestamp

            answers.append("FAIL")

    print("\n".join(answers))

