        for(int stone: stones) {
            maxHeap.offer(stone);
        }

        while(maxHeap.size() > 1) {
            int first = maxHeap.poll();
            int second = maxHeap.poll();

            if(first != second) {
                int newStone = Math.abs(first-second);
                maxHeap.offer(newStone);
            }
        }

        return 0 ? maxHeap.size() == 0 : maxHeap.poll();
    }
