class Solution {

    class Service {
        Deque<Integer> allowedRequests = new ArrayDeque<>();
    }

    public boolean[] solve(int[][] requests, int maxRequests, int windowSeconds) {
        // Write your code here
        boolean[] answers = new boolean[requests.length];
        HashMap<Integer, Service>  serviceMap = new HashMap<>();

        for(int[] request: requests)  {
            int timestamp = request[0];
            int serviceId = request[1];

            Service service = serviceMap.getOrDefault(serviceId,  new Service());

            while(!service.allowedRequests.isEmpty() && timestamp < service.allowedRequests.peekFirst() - windowSeconds +  1) {
                service.allowedRequests.removeFirst();
            }

            if(service.allowedRequests.size() > maxRequests) {
                answers.add(false);
            } else {
                service.allowedRequests.add(timestamp);
                answers.add(true);
            }

            serviceMap.put(serviceId, service);
        }
        return answers;
    }
}

